import React, { useState } from 'react';
import { Calendar, Filter, Download, ChevronDown, AlertCircle, Hash, User, Map } from 'lucide-react';

const CollectionSchedule = () => {
  const [day, setDay] = useState('22');
  const [month, setMonth] = useState('MARCH');
  const [year, setYear] = useState('2026');
  const [isManifestMode, setIsManifestMode] = useState(false);

  const scheduleLogs = [
    { id: 'SCH-1092', time: '08:45', zone: 'NORTH_SEC', area: 'Hillside Drive', code: 'HSD-44', worker: 'RAVI_K', bins: '401, 405, 409', report: 'SENSOR_ERR' },
    { id: 'SCH-1104', time: '13:20', zone: 'CENTRAL_HUB', area: 'Main Square', code: 'MSQ-01', worker: 'SITA_M', bins: '101, 102', report: null },
  ];

  return (
    <div className="w-full h-full flex flex-col gap-6 font-black italic uppercase tracking-tighter overflow-hidden">

      {/* 🛠️ THE MECHANICAL SELECTOR BAR */}
      <div className="flex flex-col lg:flex-row gap-4">

        {/* DATE ENGINE (PINK & YELLOW) */}
        <div className="relative flex-grow">
          <div className="absolute inset-0 bg-[#47510B] translate-x-1.5 translate-y-1.5 rounded-2xl" />
          <div className="relative bg-[#FFB6A9] border-[6px] border-[#47510B] rounded-2xl p-4 flex items-center gap-4">
            <div className="bg-[#47510B] p-3 rounded-xl text-[#FFF24D]"><Calendar size={24} strokeWidth={3} /></div>

            <div className="flex gap-2 flex-grow">
              {/* Day Drum */}
              <div className="flex-1 group relative">
                <select value={day} onChange={(e) => setDay(e.target.value)} className="w-full appearance-none bg-[#FFF24D] border-[4px] border-[#47510B] px-4 py-2 rounded-xl text-xl text-[#47510B] outline-none cursor-pointer">
                  {[...Array(31)].map((_, i) => <option key={i+1} value={i+1}>{String(i+1).padStart(2, '0')}</option>)}
                </select>
                <ChevronDown className="absolute right-3 top-3 text-[#47510B] pointer-events-none" size={16} />
              </div>
              {/* Month Drum */}
              <div className="flex-[2] group relative">
                <select value={month} onChange={(e) => setMonth(e.target.value)} className="w-full appearance-none bg-[#FFF24D] border-[4px] border-[#47510B] px-4 py-2 rounded-xl text-xl text-[#47510B] outline-none cursor-pointer">
                  {['JANUARY', 'FEBRUARY', 'MARCH', 'APRIL', 'MAY', 'JUNE', 'JULY', 'AUGUST', 'SEPTEMBER', 'OCTOBER', 'NOVEMBER', 'DECEMBER'].map(m => <option key={m} value={m}>{m}</option>)}
                </select>
                <ChevronDown className="absolute right-3 top-3 text-[#47510B] pointer-events-none" size={16} />
              </div>
              {/* Year Drum */}
              <div className="flex-1 group relative">
                <select value={year} onChange={(e) => setYear(e.target.value)} className="w-full appearance-none bg-[#FFF24D] border-[4px] border-[#47510B] px-4 py-2 rounded-xl text-xl text-[#47510B] outline-none cursor-pointer">
                  {['2024', '2025', '2026', '2027'].map(y => <option key={y} value={y}>{y}</option>)}
                </select>
                <ChevronDown className="absolute right-3 top-3 text-[#47510B] pointer-events-none" size={16} />
              </div>
            </div>
          </div>
        </div>

        {/* MODE SWITCHER (BLUE) */}
        <button 
          onClick={() => setIsManifestMode(!isManifestMode)}
          className="relative group transition-transform active:scale-95 lg:w-72"
        >
          <div className="absolute inset-0 bg-[#47510B] translate-x-1 translate-y-1 rounded-2xl" />
          <div className={`relative h-full border-[6px] border-[#47510B] rounded-2xl px-6 py-4 flex items-center justify-center gap-3 transition-colors ${isManifestMode ? 'bg-[#FFF24D]' : 'bg-[#A1AED1]'}`}>
            <Filter size={20} className="text-[#47510B]" />
            <span className="text-sm">MONTHLY_MANIFEST_LOG</span>
          </div>
        </button>
      </div>

      {/* 🌊 MAIN MANIFEST AREA */}
      <div className="flex-grow overflow-y-auto pr-2 custom-scrollbar pb-20">

        {!isManifestMode ? (
          <div className="flex flex-col gap-4">
            {/* HEADER LABELS */}
            <div className="grid grid-cols-12 px-8 py-2 text-[10px] text-[#47510B] opacity-50 tracking-[0.3em]">
              <div className="col-span-1">TIME</div>
              <div className="col-span-2">UNIT_ID</div>
              <div className="col-span-4">ZONE_AREA_IDENTIFIER</div>
              <div className="col-span-2">OPERATOR</div>
              <div className="col-span-2">BIN_NODES</div>
              <div className="col-span-1 text-right">REPORT</div>
            </div>

            {scheduleLogs.map((log) => (
              <div key={log.id} className="relative group">
                <div className="absolute inset-0 bg-[#47510B] translate-x-1 translate-y-1 rounded-2xl" />
                <div className="relative bg-white border-[4px] border-[#47510B] rounded-2xl p-6 grid grid-cols-12 items-center group-hover:bg-[#FDFAD8] transition-colors">

                  {/* Time & ID */}
                  <div className="col-span-1 text-2xl text-[#47510B] font-[1000]">{log.time}</div>
                  <div className="col-span-2">
                    <span className="bg-[#A1AED1] px-3 py-1 rounded-lg border-2 border-[#47510B] text-[10px]">{log.id}</span>
                  </div>

                  {/* Zone & Area */}
                  <div className="col-span-4">
                    <p className="text-[10px] text-[#AB1717] leading-none mb-1">{log.zone} // {log.code}</p>
                    <h3 className="text-xl text-[#47510B] leading-none">{log.area}</h3>
                  </div>

                  {/* Worker */}
                  <div className="col-span-2 flex items-center gap-2">
                    <div className="w-8 h-8 bg-[#47510B] rounded-lg flex items-center justify-center text-[#FFF24D]"><User size={16} /></div>
                    <span className="text-xs">{log.worker}</span>
                  </div>

                  {/* Bins */}
                  <div className="col-span-2 flex items-center gap-2">
                     <Hash size={14} className="text-[#A1AED1]" />
                     <span className="text-[10px] font-mono opacity-60">{log.bins}</span>
                  </div>

                  {/* Report Alert */}
                  <div className="col-span-1 flex justify-end">
                    {log.report ? (
                      <div className="w-10 h-10 bg-[#AB1717] rounded-full flex items-center justify-center text-white border-2 border-[#47510B] animate-pulse cursor-help" title={log.report}>
                        <AlertCircle size={20} />
                      </div>
                    ) : (
                      <div className="w-2 h-2 rounded-full bg-[#CAD23C]" />
                    )}
                  </div>
                </div>
              </div>
            ))}
          </div>
        ) : (
          /* 📦 MONTHLY ARCHIVE VIEW */
          <div className="relative pt-4 h-full">
            <div className="absolute inset-0 bg-[#47510B] translate-x-2 translate-y-2 rounded-[40px]" />
            <div className="relative h-full bg-[#A1AED1] border-[6px] border-[#47510B] rounded-[40px] flex flex-col items-center justify-center p-10 text-center">
              <div className="w-32 h-32 bg-[#FFB6A9] border-[6px] border-[#47510B] rounded-full flex items-center justify-center shadow-[6px_6px_0_0_#FFF24D] mb-8">
                <Download size={48} className="text-[#47510B]" />
              </div>
              <h2 className="text-6xl text-[#47510B] leading-tight mb-4">FULL_MONTH_MANIFEST</h2>
              <p className="max-w-md text-xs opacity-60 mb-10 tracking-widest">COMPILE ALL LOGS FROM {month} {year} INTO A TECHNICAL DATASHEET FOR AUDIT PURPOSES.</p>
              <div className="flex gap-4 w-full max-w-lg">
                <button className="flex-1 py-4 bg-[#47510B] text-white rounded-2xl border-4 border-white shadow-[4px_4px_0_0_#AB1717] hover:bg-[#AB1717] transition-all">GENERATE_CSV</button>
                <button className="flex-1 py-4 bg-white text-[#47510B] rounded-2xl border-4 border-[#47510B] shadow-[4px_4px_0_0_#47510B]">SYNC_CLOUD</button>
              </div>
            </div>
          </div>
        )}
      </div>

      {/* 🧭 STATUS LINE */}
      <div className="fixed bottom-10 left-80 right-10 flex justify-between px-10 pointer-events-none">
         <div className="bg-[#47510B] text-[#FFF24D] px-6 py-2 rounded-full border-2 border-white shadow-xl text-[10px] flex items-center gap-3">
            <div className="w-2 h-2 rounded-full bg-[#CAD23C]" /> ARCHIVE_CONNECTION: STABLE
         </div>
         <div className="bg-[#47510B] text-[#FFB6A9] px-6 py-2 rounded-full border-2 border-white shadow-xl text-[10px]">
            ACTIVE_DATE_FILTER: {day}_{month}_{year}
         </div>
      </div>

    </div>
  );
};

export default CollectionSchedule;
